/**
 * THE ONE GENERATED SCHEMA TYPE, reached from the package rather than copied into it.
 *
 * `types/database.types.ts` is generated from the live schema by the Supabase CLI. Copying it here so
 * the package could be self-contained would create exactly what section 28 forbids -- a WebTeam and a
 * MobileTeam for one canonical concept -- and the copy would be wrong the first time anybody ran a
 * migration without remembering it existed. One generated file, one source, reached by a relative path
 * because that is what both the Next.js compiler and Metro can follow without configuration.
 */
export type { Database, Json } from "../../../types/database.types"
